        if len(changed) != len(net):
            return None
        return tuple(sorted(changed))

    def propose(net, detail):
        arcs = list(net)
        current = edges(net)
        moves = set()

        prices = detail.get("prices", {}) if detail else {}
        hot = {
            tuple(map(int, link))
            for link, price in prices.items()
            if float(price) > 0
        }
        loads = detail.get("loads", {}) if detail else {}
        if loads:
            ranked_loads = sorted(
                ((float(value), tuple(map(int, link))) for link, value in loads.items()),
                reverse=True,
            )
            hot.update(link for _, link in ranked_loads[:6])

        # Exhaustive two-switches involving a bottleneck, supplemented by a
        # small unrestricted sample so that dual prices do not define the
        # entire neighborhood.
        for p in range(len(arcs)):
            for q in range(p + 1, len(arcs)):
                if hot and arcs[p] not in hot and arcs[q] not in hot:
                    continue
                move = switch(net, p, q)
                if move is not None:
                    moves.add(move)

        for _ in range(55):
            if len(arcs) < 2:
                break
            p = int(rng.integers(len(arcs)))
            q = int(rng.integers(len(arcs) - 1))
            if q >= p:
                q += 1
            move = switch(net, p, q)
            if move is not None:
                moves.add(move)

        # Degree-preserving 3-link rotations, increased modestly for a
        # repeatedly stalled parent.
        if len(arcs) >= 3:
            trials = min(240, 65 * (1 + stalls.get(net, 0) // 3))
            for _ in range(trials):
                ids = rng.choice(len(arcs), size=3, replace=False)
                (a, b), (c, d), (e, f) = (arcs[int(i)] for i in ids)
                old = {(a, b), (c, d), (e, f)}
                if hot and not (old & hot):
                    continue
                for new in (
                    {(a, d), (c, f), (e, b)},
                    {(a, f), (c, b), (e, d)},
                ):
                    if len(new) != 3 or any(u == v for u, v in new):
                        continue
                    if new & (current - old):
                        continue
                    moves.add(tuple(sorted((current - old) | new)))

        # Multi-switch perturbations broaden exploration past one-move basins.
        for _ in range(12):
            changed = set(net)
            for _ in range(2 + int(rng.integers(4))):
                now = list(changed)
                if len(now) < 2:
                    break
                p, q = rng.choice(len(now), size=2, replace=False)
                (a, b), (c, d) = now[int(p)], now[int(q)]
                if a == d or c == b or (a, d) in changed or (c, b) in changed:
                    continue
                changed.remove((a, b))
                changed.remove((c, d))
                changed.add((a, d))
                changed.add((c, b))
            if changed != current:
                moves.add(tuple(sorted(changed)))

        # When stalled, add a short bridge toward a strong, distant archive
        # member. Keep this bounded to avoid spending time on exhaustive paths.
        if stalls.get(net,  0) >= 2:
            targets = [
                x for x in sorted(scores, key=scores.get)[:12]
                if x != net and distance(x, net) >= 6
            ]
            if targets:
                target = targets[int(rng.integers(len(targets)))]
                target_edges = edges(target)
                walk = net
                for _ in range(4):
                    walk_arcs = list(walk)
                    walk_edges = edges(walk)
                    overlap = len(walk_edges & target_edges)
                    advancing = []
                    best_overlap = overlap
                    for p in range(len(walk_arcs)):
                        for q in range(p + 1, len(walk_arcs)):
                            candidate = switch(walk, p, q)
                            if candidate is None:
                                continue
                            new_overlap = len(edges(candidate) & target_edges)
                            if new_overlap > best_overlap:
                                best_overlap = new_overlap
                                advancing = [candidate]
                            elif new_overlap == best_overlap and new_overlap > overlap:
                                advancing.append(candidate)
                    if not advancing:
                        break
                    walk = advancing[int(rng.integers(len(advancing)))]
                    moves.add(walk)

        return [
            move for move in moves
            if move != net
            and move not in scores
            and not tools.is_cached(move)
            and tools.is_valid(move)
        ]

    def select_batch(moves, parent, limit=4):
        if not moves:
            return []
        base_energy = energy(parent)
        ranked = sorted(moves, key=lambda net: energy(net) - base_energy)
        selected = []

        # Surrogate-favored but structurally distinct proposals.
        diverse_goal = 2 if stalls.get(parent, 0) >= 2 else min(3, limit)
        for net in ranked:
            if all(distance(net, old) >= 2 for old in selected):
                selected.append(net)
            if len(selected) >= diverse_goal:
                break

        # Reserve a slot for novelty against several strong archive regions,
        # not just distance from this parent or the current batch.
        if len(selected) < limit and len(ranked) > 8:
            anchors = sorted(scores, key=scores.get)[:8]
            pool = [
                net for net in ranked
                if net not in selected
                and all(distance(net, old) >= 2 for old in selected)
            ]
            if pool and anchors:
                base_energy = energy(parent)
                novel = max(
                    pool,
                    key=lambda net: (
                        sum(distance(net, anchor) for anchor in anchors) / len(anchors),
                        -(energy(net) - base_energy),
                    ),
                )
                selected.append(novel)

        for net in ranked:
            if len(selected) >= limit:
                break
            if net not in selected:
                selected.append(net)
        return selected[:limit]

    rounds = 0
    while tools.lp_calls_left > 0:
        rounds += 1
        pop = archive()
        parent = choose_parent(pop)
        if parent is None:
            break
        visits[parent] = visits.get(parent, 0) + 1

        try:
            detail = tools.lp_detail(parent)
        except Exception:
            detail = None

        batch = select_batch(propose(parent, detail), parent)

        # Try lightly visited archive members if this neighborhood is used up.
        if not batch:
            alternatives = sorted(
                (net for net in pop if net != parent),
                key=lambda net: visits.get(net, 0),
            )
            for alternative in alternatives[:6]:
                try:
                    alt_detail = tools.lp_detail(alternative)
                except Exception:
                    alt_detail = None
                batch = select_batch(propose(alternative, alt_detail), alternative)
                if batch:
                    parent = alternative
                    visits[parent] = visits.get(parent, 0) + 1
                    break

        if not batch:
            # Last-resort random degree-preserving kicks.
            for _ in range(35):
                changed = set(parent)
                for _ in range(3 + int(rng.integers(4))):
                    now = list(changed)
                    p, q = rng.choice(len(now), size=2, replace=False)
                    (a, b), (c, d) = now[int(p)], now[int(q)]
                    if a == d or c == b or (a, d) in changed or (c, b) in changed:
                        continue
                    changed.remove((a, b))
                    changed.remove((c, d))
                    changed.add((a, d))
                    changed.add((c, b))
                kicked = tuple(sorted(changed))
                if (
                    kicked != parent and kicked not in scores
                    and not tools.is_cached(kicked) and tools.is_valid(kicked)
                ):
                    batch = [kicked]
                    break

        if not batch:
            if rounds > 10000:
                break
            continue

        parent_score = scores.get(parent, float("inf"))
        batch_best = float("inf")
        for net in batch:
            if tools.lp_calls_left <= 0:
                break
            try:
                batch_best = min(batch_best, evaluate(net))
            except Exception as exc:
                if type(exc).__name__ == "BudgetExhausted":
                    return list(best_net) if best_net is not None else []
                continue

        if batch_best < parent_score:
            stalls[parent] = 0
            gains[parent] = gains.get(parent, 0) + 1
        else:
            stalls[parent] = stalls.get(parent, 0) + 1

    return list(best_net) if best_net is not None else []
# EVOLVE-BLOCK-END


def run_postproc(pool_path, lp_budget, seed, control=False, time_limit=150):
    """Fixed entry point called by the evaluator: one run on one candidate pool."""
    import importlib.util
    import signal
    from pathlib import Path

    import oracle

    pool = json.load(open(pool_path))
    import qoblib_tools as qt

    if "hamiltonian_file" in pool:  # the Hamiltonian that sampled this pool (make_pools.py --tag)
        spec = importlib.util.spec_from_file_location(
            f"hamiltonian_{pool['hamiltonian_tag']}", Path(pool_path).resolve().parent / pool["hamiltonian_file"])
        ham = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(ham)
        surrogate_terms = ham.surrogate_terms
    else:  # older pools: the frozen run 3 gen 28 Hamiltonian
        from hamiltonian import surrogate_terms

    n = int(pool["instance"][-2:])
    demand = qt.load_network_demand(n)
    linear, quadratic, _ = surrogate_terms(np.array(demand, dtype=float))
    tools = oracle.Tools(demand, lp_budget, (
        {tuple(map(int, a)): float(w) for a, w in linear.items()},
        {(tuple(map(int, a)), tuple(map(int, b))): float(w) for (a, b), w in quadratic.items()},
    ))
    candidates = [[tuple(map(int, a)) for a in c["arcs"]] for c in pool["candidates"]]
    if control:  # same number of random valid networks instead of QAOA output
        crng = np.random.default_rng(10_000 + seed)
        candidates = [qt.random_topology(n, crng) for _ in candidates]
    def _timeout(signum, frame):
        raise oracle.RunTimeout()

    start = time.perf_counter()
    returned, error, timed_out = None, None, False
    signal.signal(signal.SIGALRM, _timeout)
    signal.alarm(int(time_limit))
    try:
        returned = improve(demand.copy(), candidates, tools, np.random.default_rng(seed))
    except oracle.BudgetExhausted:
        pass
    except oracle.RunTimeout:
        timed_out = True
    except Exception as exc:  # noqa: BLE001
        error = f"{type(exc).__name__}: {exc}"
    finally:
        signal.alarm(0)
    best_score, best_arcs = tools.certified_best()
    if returned is not None:
        try:
            ret = [tuple(map(int, a)) for a in returned]
            if qt.is_valid_topology(n, ret):
                s = qt.route_min_congestion(demand, ret).objective
                if s < best_score:
                    best_score, best_arcs = s, tuple(sorted(ret))
        except Exception:  # noqa: BLE001
            pass
    return {
        "pool": pool_path, "control": control, "n": n, "error": error,
        "best": float(best_score), "arcs": [list(a) for a in best_arcs] if best_arcs else None,
        "lp_calls": tools.lp_calls_used, "seconds": time.perf_counter() - start, "timed_out": timed_out,
    }

