        stalls = parent_stalls.get(parent, 0)
        if stalls >= 2 and batch_size >= 3:
            # Retain two high-ranked trials, then spend one LP call exploring
            # beyond the surrogate's preferred neighborhood.
            for _, net in ranked:
                if all(distance(net, old) >= 2 for old in selected):
                    selected.append(net)
                if len(selected) >= 2:
                    break
            exploratory = [
                net for _, net in ranked
                if net not in selected
                and all(distance(net, old) >= 2 for old in selected)
            ]
            if not exploratory:
                exploratory = [net for _, net in ranked if net not in selected]
            if exploratory:
                rng.shuffle(exploratory)
                selected.append(exploratory[0])
        else:
            # First take good-energy moves that are not all tiny variants of one another.
            for _, net in ranked:
                if all(distance(net, old) >= 2 for old in selected):
                    selected.append(net)
                if len(selected) >= min(6, batch_size):
                    break

        # Fill remaining slots with the best surrogate-ranked moves.
        for _, net in ranked:
            if len(selected) >= batch_size:
                break
            if net not in selected:
                selected.append(net)

        # Reserve a little batch capacity for tail exploration.
        tail = [net for _, net in ranked if net not in selected]
        if tail and len(selected) >= 4 and len(selected) < batch_size:
            rng.shuffle(tail)
            selected.extend(tail[:batch_size - len(selected)])
        return selected[:batch_size]

